<?php
namespace App\Http\Controllers\Admin;use App\Http\Controllers\Controller;use App\Models\{Gallery,Media};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;class GalleryController extends Controller{public function index(){return view('admin.galleries.index',['items'=>Gallery::withCount('media')->latest('event_date')->paginate(30)]);}public function create(){return view('admin.galleries.form',['item'=>new Gallery]);}public function store(Request $r){$gallery=Gallery::create($this->data($r));$this->photos($r,$gallery);return redirect()->route('admin.galleries.edit',$gallery)->with('ok','Альбом создан');}public function edit(Gallery $gallery){$gallery->load('media');return view('admin.galleries.form',['item'=>$gallery]);}public function update(Request $r,Gallery $gallery){$oldCover=$gallery->cover;$data=$this->data($r);$gallery->update($data);if(isset($data['cover'])&&$oldCover&&$oldCover!==$data['cover'])Storage::disk('public')->delete($oldCover);$this->photos($r,$gallery);return back()->with('ok','Альбом сохранён');}public function detach(Gallery $gallery,Media $medium){$gallery->media()->detach($medium->id);return back()->with('ok','Фото удалено из альбома');}public function destroy(Gallery $gallery){if($gallery->cover)Storage::disk('public')->delete($gallery->cover);$gallery->media()->detach();$gallery->delete();return back();}private function data(Request $r){$d=$r->validate(['title'=>'required|max:255','description'=>'nullable','event_date'=>'nullable|date','cover'=>'nullable|image|max:10240']);$d['slug']=Str::slug($r->input('slug')?:$d['title']);if($r->hasFile('cover'))$d['cover']=$r->file('cover')->store('galleries/covers','public');$d['is_published']=$r->boolean('is_published');return $d;}private function photos(Request $r,Gallery $gallery):void{$r->validate(['photos.*'=>'image|max:15360|mimes:jpg,jpeg,png,webp,avif']);foreach($r->file('photos',[]) as $file){$path=$file->store('galleries/'.date('Y/m'),'public');$media=Media::create(['name'=>$file->getClientOriginalName(),'file'=>$path,'mime'=>$file->getMimeType(),'size'=>$file->getSize(),'collection'=>'gallery']);$gallery->media()->attach($media->id,['sort'=>$gallery->media()->count()]);}}}